g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "x": 80, "y": 400, "width": 1080, "height": 820,
  "name": "study-comparability",
  "header_rows": 1,
  "column_widths": [190, 400, 250, 240],
  "row_heights": [80, 110, 110, 110, 80, 110, 110, 110],
  "defaults": {
    "cell": {
      "valign": "top",
      "align": "l",
      "padding": {"left": 8, "right": 8, "top": 10, "bottom": 10},
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "none"},
        "bottom": {"style": "solid", "color": "#E7E3DB", "width": 1}
      }
    },
    "run": {"color": "#16232E"}
  },
  "columns": [
    {"text": "Study", "bold": true, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "What changed, and what it found", "bold": true, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Scale, period, control", "bold": true, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Evidence about a firm like ours?", "bold": true, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}}
  ],
  "rows": [
    ["UK 2022 pilot", "Real hours cut at full pay; 92% still running it at the end", "61 companies · Jun–Dec 2022 · no control", {"text": "Yes, with a scale caveat", "color": "#16232E"}],
    ["UK follow-up 2024", "89% still on reduced hours a year on; the one firm that stopped was a consultancy", "28 of 61 · 2024 · no control", {"text": "Yes — the closest case we have", "color": "#16232E"}],
    ["Iceland 2015–19", "40 hours to 35–36 and service levels held. Veal: 61 of 66 sites cut only one to three hours", "~2,940 workers · 2015–2019 · no control", {"text": "No — public sector, a 1–3 hour cut", "color": "#6E777E"}],
    ["Belgium 2022", "A right to compress 38 hours into four days; hours and pay unchanged", "National law · from Nov 2022", {"text": "No — not an hours reduction", "color": "#6E777E"}],
    ["Portugal 2023–24", "Actual hours down 12%, 41+ to 36.5; the authors call it a proof of concept", "41 companies · from Jun 2023 · non-adopter control", {"text": "Partly — best design, other sectors", "color": "#4A6B7C"}],
    ["Germany 2024", "Stress and burnout down significantly; sick days, turnover and profit not", "45 orgs · 6 months from Feb 2024 · in-house control", {"text": "Partly — best method, mixed model", "color": "#4A6B7C"}],
    ["South Cambridgeshire", "32 hours at full pay; 11 outcomes better, 2 worse, the rest indistinguishable", "One council · from Jan 2023 · COVID-adjusted", {"text": "No — statutory public services", "color": "#6E777E"}]
  ],
  "style": {
    "font_family": "Arial",
    "font_size": 22,
    "header_font_size": 22,
    "header_fill": "#F2F0EB",
    "header_text": "#16232E",
    "body_text": "#16232E",
    "band_row": false
  }
}
